{% image https://tzyy-1330068502.cos.ap-beijing.myqcloud.com/%E6%B3%A1%E6%B3%A1%E7%B3%96%E5%AD%98%E5%82%A8/06/%E5%9B%BE%E7%89%8761.png, alt=通关提示流程, width=450px %}

{% folding blue, isChangeLevel类 %}
```
public boolean isChangeLevel(int score) {
    // 获取泡泡糖游戏的分数配置信息，包含当前关卡的通关分数要求
    Score s = this.mConfiguration.getScore();
    // 若当前分数达到或超过当前关卡的通关分数，则满足条件
    if (score >= s.getLevelScore()) {
        return true;
    }

    // 未达到条件，返回false
    return false;
}

```
{% endfolding %}

{% folding green, isNoticePassLevel类 %}
```
public boolean isNoticePassLevel(int currentLevel, int score) {
    // 先判断当前分数是否达到关卡升级条件（即通关条件）
    if (isChangeLevel(score)) {
        // 若关卡计数器与当前关卡一致（表示首次达到该关卡通关条件）
        if (this.mLevelCounter == currentLevel) {
            // 将关卡计数器+1，标记为已处理过该关卡的通关提示
            this.mLevelCounter++;
            // 返回true，表示需要显示通关提示
            return true;
        } else {
            // 非首次触发该关卡通关，无需重复提示
            return false;
        }
    }
    // 未达到通关条件，无需提示
    return false;
}

```
