      public int value(){
        return this.value;
      }

      // 静态方法，根据数值获取对应的星星类型
      public static StarType valueOf(int value){
        switch(value){
        case 0:
          return BLUE;
        case 1:
          return GREEN;
        case 2:
          return YELLOW;
        case 3:
          return RED;
        case 4:
          return PURPLE;
        default:
  return null; // 数值不匹配时返回null
        }
       }
      }

