public static Star clone(Star star) {
    // 创建一个新的泡泡糖对象作为克隆结果
    Star ret = new Star();

    // 复制原泡泡糖的位置信息，创建新的Position对象以避免引用共享
    ret.setPosition(new Position(star.getPosition().getRow(), star.getPosition().getColumn()));

    // 复制原泡泡糖的类型信息
    ret.setType(star.getType());

    // 返回克隆得到的新泡泡糖对象
    return ret;
}

```
