{% folding blue, existed类 %}
```
// 判断指定泡泡糖是否存在于列表中
public boolean existed(Star star) {
    // 若传入的泡泡糖为null，直接返回不存在
    if (star == null)
        return false;

    // 根据泡泡糖的位置查找列表中是否有匹配的泡泡糖
    Star ret = lookup(star.getPosition());

    // 若找到匹配的泡泡糖则返回true，否则返回false
    return ret == null ? false : true;
}

