public boolean isNoticePassLevel(int currentLevel, int score) {
    // 先判断当前分数是否达到关卡升级条件（即通关条件）
    if (isChangeLevel(score)) {
        // 若关卡计数器与当前关卡一致（表示首次达到该关卡通关条件）
        if (this.mLevelCounter == currentLevel) {
            // 将关卡计数器+1，标记为已处理过该关卡的通关提示
            this.mLevelCounter++;
            // 返回true，表示需要显示通关提示
            return true;
        } else {
            // 非首次触发该关卡通关，无需重复提示
            return false;
        }
    }
    // 未达到通关条件，无需提示
    return false;
}

